import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2025-05-21","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2025-05-21","date":"2025-05-21T00:00:00.000Z","updated":"2025-05-24T00:00:00.000Z","tags":["Ceph","RGW","Distributed Storage","Erasure Coding","Scale Testing"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-05-21.md","filePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-05-21.md","lastUpdated":1780460162000}'),n={name:"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-05-21.md"};function i(l,t,s,g,p,c){return a(),o("div",null,[...t[0]||(t[0]=[r('<h3 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h3><p>本次 Ceph RGW (RADOS Gateway) 开发组会议主要讨论了以下技术议题：</p><ol><li><strong>Bucket Logging 性能问题及解决方案</strong>：讨论了在 Erasure Coding (EC) 池中使用 Bucket Logging 功能时的性能问题，并提出了使用专用 replica pool 作为临时对象池的解决方案。</li><li><strong>RGW 客户端超时处理机制</strong>：讨论了客户端超时断开时 RGW 的处理机制，确认了当前机制的有效性。</li><li><strong>版本控制与分片方案改进</strong>：讨论了当前分片方案对版本化对象数量有限制的问题，并提出了改进方案。</li><li><strong>Tentacle 版本发布前的功能合并状态</strong>：讨论了 Tentacle 版本发布准备情况，包括待合并功能和测试验证。</li></ol><h3 id="主要议题与讨论" tabindex="-1">主要议题与讨论 <a class="header-anchor" href="#主要议题与讨论" aria-label="Permalink to &quot;主要议题与讨论&quot;">​</a></h3><h4 id="_1-bucket-logging-性能问题" tabindex="-1">1. Bucket Logging 性能问题 <a class="header-anchor" href="#_1-bucket-logging-性能问题" aria-label="Permalink to &quot;1. Bucket Logging 性能问题&quot;">​</a></h4><p><strong>问题描述</strong>：Bucket Logging 功能在 EC 池中存在性能问题，因为 EC 池默认不支持 append 操作，修改对象需要重写整个对象。</p><p><strong>讨论方案</strong>：</p><ul><li>使用 replica pool 作为临时对象池，写入时先写入临时池，提交时通过更新 manifest 使对象可见。</li><li>使用现有的 RGW &quot;data extra pool&quot; 作为临时对象池。</li></ul><p><strong>决议</strong>：采用方案B，通过 manifest 指向不同池中的对象。</p><h4 id="_2-rgw-客户端超时处理" tabindex="-1">2. RGW 客户端超时处理 <a class="header-anchor" href="#_2-rgw-客户端超时处理" aria-label="Permalink to &quot;2. RGW 客户端超时处理&quot;">​</a></h4><p><strong>问题描述</strong>：客户端读取大文件时超时断开，RGW 仍会继续从 OSD 获取数据。</p><p><strong>讨论结果</strong>：当前机制已合理限制资源浪费，16MB 窗口大小可通过配置调整。</p><h4 id="_3-版本控制与分片方案改进" tabindex="-1">3. 版本控制与分片方案改进 <a class="header-anchor" href="#_3-版本控制与分片方案改进" aria-label="Permalink to &quot;3. 版本控制与分片方案改进&quot;">​</a></h4><p><strong>问题背景</strong>：当前分片方案对版本化对象数量有限制（约200,000个）。</p><p><strong>讨论方案</strong>：</p><ul><li>顺序分片方案（In-order sharding）。</li><li>版本数量限制作为可选功能提供给用户。</li></ul><p><strong>决议</strong>：优先开发 in-order sharding 方案，版本数量限制作为可选功能。</p><h4 id="_4-tentacle-版本发布状态" tabindex="-1">4. Tentacle 版本发布状态 <a class="header-anchor" href="#_4-tentacle-版本发布状态" aria-label="Permalink to &quot;4. Tentacle 版本发布状态&quot;">​</a></h4><p><strong>待合并功能</strong>：</p><ul><li>D4N (Direct-to-Daemon NFS) 视为 bug fix，可合并。</li><li>DDUP (Data Deduplication) 尚未通过全部测试。</li></ul><p><strong>发布决策</strong>：若 DDUP 能在一周内通过全部测试，可纳入 Tentacle；否则将推迟到点发布版本。</p><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ol><li><strong>Bucket Logging 改进</strong>：实现基于 manifest 的跨池方案，验证性能并确保垃圾回收机制正常工作。</li><li><strong>版本控制改进</strong>：推进 in-order sharding 方案开发，评估版本数量限制功能的实现方式。</li><li><strong>Tentacle 发布准备</strong>：加速 DDUP 功能测试验证，跟踪 multi-site 测试中发现的数据日志问题，确定最终功能合并截止时间。</li><li><strong>客户端超时优化</strong>：文档化当前 16MB 窗口配置选项，评估是否需要提供更细粒度的超时控制。</li></ol><h3 id="关键技术点" tabindex="-1">关键技术点 <a class="header-anchor" href="#关键技术点" aria-label="Permalink to &quot;关键技术点&quot;">​</a></h3><ul><li><strong>EC 池限制</strong>：默认不支持 append 操作，修改需重写整个对象。</li><li><strong>RGW 缓冲机制</strong>：默认 16MB 传输窗口，可通过配置调整。</li><li><strong>分片方案</strong>：当前方案在大规模对象下性能下降，in-order sharding 有望改善。</li><li><strong>Data extra pool</strong>：RGW 已有用于 multipart upload 的专用临时池。</li></ul>',25)])])}const u=e(n,[["render",i]]);export{h as __pageData,u as default};
